sys_ui_action.script:
/**
 * UI Action: Download Invoice PDF
 * Table: x_2223823_apollo_0_invoice
 * Action Name: apollo_invoice_download_pdf
 * Form Button: true
 * Form Context Menu: true
 * Client: false (Runs server-side directly)
 * Condition: current.total_amount > 0
 * 
 * Generates an official Apollo Hospitals Invoice PDF with itemized charges,
 * status badges (PAID / PENDING), patient & hospital details, and receipts,
 * then triggers immediate browser file download.
 */
(function executeAction(current) {
    try {
        var utils = new x_2223823_apollo_0.ApolloPaymentUtils();
        var res = utils.generateInvoicePDF(current);

        if (res && res.success && res.attachment_id) {
            // Direct browser download of the generated PDF attachment
            action.setRedirectURL('/sys_attachment.do?sys_id=' + res.attachment_id);
        } else {
            var msg = (res && res.message) ? res.message : 'Failed to generate invoice PDF.';
            gs.addErrorMessage('Apollo Billing: ' + msg);
            action.setRedirectURL(current);
        }
    } catch (e) {
        gs.error('[Apollo Download Invoice PDF] ' + e.message);
        gs.addErrorMessage('Error generating invoice PDF: ' + e.message);
        action.setRedirectURL(current);
    }
})(current);
